function readRecords(key, fallbackKey) {
  try {
    const raw = localStorage.getItem(key) ?? (fallbackKey ? localStorage.getItem(fallbackKey) : null);
    if (raw == null) return [];
    const data = JSON.parse(raw);
    if (Array.isArray(data)) return data;
    for (const field of ["data", "records", "items", "list", "customers", "bookings", "deliveries", "selections"]) if (Array.isArray(data?.[field])) return data[field];
  } catch (error) { console.error(`Cannot read ${key}`, error); }
  return [];
}
