function useSounds() {
  const ctx = useRef(null);
  useEffect(() => () => { if (ctx.current && ctx.current.state !== "closed") ctx.current.close().catch(() => {}); }, []);
  return (kind = "click") => { try { if (localStorage.getItem(SOUND_KEY) === "false") return; const AC = window.AudioContext || window.webkitAudioContext; if (!AC) return; if (!ctx.current || ctx.current.state === "closed") ctx.current = new AC(); if (ctx.current.state === "suspended") ctx.current.resume().catch(() => {}); const freqs = { click: [600], open: [520, 720], success: [520, 660, 880], delete: [460, 310], error: [240, 200] }; (freqs[kind] || freqs.click).forEach((f, i) => { const c = ctx.current, o = c.createOscillator(), g = c.createGain(), t = c.currentTime + i * 0.095, duration = kind === "success" ? 0.13 : 0.09; o.type = "sine"; o.frequency.setValueAtTime(f, t); g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.04, t + 0.012); g.gain.exponentialRampToValueAtTime(0.0001, t + duration); o.connect(g); g.connect(c.destination); o.start(t); o.stop(t + duration + 0.01); }); } catch {} };
}
