      {matches.length > 0 && <div className=""><Field label="Linked Shoot / Booking"><select value={form.bookingId || ""} onChange={e => chooseBooking(e.target.value, kind)} className={inputClass}><option value="">-- Choose Shoot / Booking --</option>{matches.map(b => <option key={String(b.id)} value={String(b.id)}>{b.event || b.eventType || "Shoot"} ({b.date || b.eventDate || "Scheduled"}) · {b.id}</option>)}</select></Field></div>}
      {form.eventDate && <Field label="Event Date"><input readOnly value={formatDate(form.eventDate)} className={`${inputClass} bg-[#edf5ff]`}/></Field>}
