export default function Delivery() {
  const sound = useSounds();
  const [deliveries, setDeliveries] = useState(() => readSaved(DELIVERY_KEY, DEMO_DELIVERIES));
  const [selections, setSelections] = useState(() => readSaved(SELECTION_KEY, DEMO_SELECTIONS));
  const [customers, setCustomers] = useState(() => readRecords(CUSTOMER_KEY, "studioraw_customers"));
  const [bookings, setBookings] = useState(() => readRecords(BOOKING_KEY, "studio_raw_bookings"));
  const [activeTab, setActiveTab] = useState("selection");
  const [deliveryForm, setDeliveryForm] = useState(emptyDelivery);
  const [selectionForm, setSelectionForm] = useState(emptySelection);
  const [formType, setFormType] = useState(null);
  const [editingId, setEditingId] = useState(null);
  const [viewType, setViewType] = useState(null);
  const [viewId, setViewId] = useState(null);
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("All");
  const [error, setError] = useState("");
  const [statusError, setStatusError] = useState("");
  const refresh = () => { setCustomers(readRecords(CUSTOMER_KEY, "studioraw_customers")); setBookings(readRecords(BOOKING_KEY, "studio_raw_bookings")); };
  useEffect(() => {
    let isMounted = true;
    api.deliveries.list().then(res => {
      const items = Array.isArray(res) ? res : res?.results;
      if (isMounted && Array.isArray(items) && items.length > 0) {
        const mapped = items.map(d => ({
          id: d.id,
          customerId: d.customer || "",
          bookingId: d.booking || "",
          customer: d.customer_name || "Customer",
          phone: d.phone || "",
          event: "Photography",
          item: d.item_name || "Wedding Album",
          quantity: d.quantity || 1,
          deliveryMethod: "Home Delivery",
          address: d.address || "",
          trackingNumber: d.tracking_number || "",
          deliveredDate: d.delivery_date || "",
          expectedDate: d.delivery_date || "",
          status: d.status || "Pending",
          paymentStatus: d.payment_status || "Pending",
          notes: d.notes || "",
        }));
        setDeliveries(mapped);
      }
    }).catch(err => console.warn("Using local deliveries fallback:", err.message));
    const onChange = () => refresh(); window.addEventListener("storage", onChange); window.addEventListener(UPDATE_EVENT, onChange); window.addEventListener("focus", onChange); return () => { isMounted = false; window.removeEventListener("storage", onChange); window.removeEventListener(UPDATE_EVENT, onChange); window.removeEventListener("focus", onChange); };
  }, []);
  useEffect(() => { localStorage.setItem(DELIVERY_KEY, JSON.stringify(deliveries)); window.dispatchEvent(new CustomEvent(UPDATE_EVENT, { detail: { key: DELIVERY_KEY } })); }, [deliveries]);
  useEffect(() => { localStorage.setItem(SELECTION_KEY, JSON.stringify(selections)); window.dispatchEvent(new CustomEvent(UPDATE_EVENT, { detail: { key: SELECTION_KEY } })); }, [selections]);
  useEffect(() => { if (!formType && !viewType) return; const old = document.body.style.overflow; document.body.style.overflow = "hidden"; const onKey = e => { if (e.key === "Escape") { setFormType(null); setViewType(null); } }; document.addEventListener("keydown", onKey); return () => { document.body.style.overflow = old; document.removeEventListener("keydown", onKey); }; }, [formType, viewType]);
  const customerOptions = useMemo(() => customers.filter(c => c?.id != null && nameOf(c)), [customers]);
  const bookingMatches = (customerId, phone) => bookings.filter(b => String(b.customerId || "") === String(customerId) && !!customerId || (phone && phoneOf(b) === phone));
  const deliveryBookings = useMemo(() => deliveryForm.customerId ? bookingMatches(deliveryForm.customerId, phoneOf(deliveryForm)) : [], [bookings, deliveryForm.customerId, deliveryForm.phone]);
  const selectionBookings = useMemo(() => selectionForm.customerId ? bookingMatches(selectionForm.customerId, phoneOf(selectionForm)) : [], [bookings, selectionForm.customerId, selectionForm.phone]);
  const chooseCustomer = (id, kind) => {
    const c = customers.find(c => String(c.id) === String(id));
    const setter = kind === "delivery" ? setDeliveryForm : setSelectionForm;
    if (!c) { setter(p => ({ ...p, customerId: "", bookingId: "", customer: "", phone: "", email: "", ...(kind === "delivery" ? { address: "", eventDate: "" } : { eventDate: "" }) })); setError(""); return; }
    const phone = phoneOf(c), matches = bookingMatches(String(c.id), phone), b = matches.length === 1 ? matches[0] : null;
    setter(p => ({ ...p, customerId: String(c.id), customer: nameOf(c), phone, email: emailOf(c), bookingId: b ? String(b.id) : "", eventDate: b ? String(b.date || b.eventDate || "").slice(0, 10) : "", ...(kind === "delivery" ? { address: addressOf(c), event: b ? (b.event || b.eventType || b.package || EVENTS[0]) : EVENTS[0] } : { project: b ? (b.event || b.eventType || b.package || EVENTS[0]) : EVENTS[0] }) }));
    setError(""); sound("click");
  };
  const chooseBooking = (id, kind) => { const b = bookings.find(b => String(b.id) === String(id)); const setter = kind === "delivery" ? setDeliveryForm : setSelectionForm; setter(p => ({ ...p, bookingId: b ? String(b.id) : "", eventDate: b ? String(b.date || b.eventDate || "").slice(0, 10) : "", ...(b ? { [kind === "delivery" ? "event" : "project"]: b.event || b.eventType || b.package || p[kind === "delivery" ? "event" : "project"] } : {}) })); sound("click"); };
  const updateD = (k, v) => { setDeliveryForm(p => ({ ...p, [k]: v })); setError(""); };
  const updateS = (k, v) => { setSelectionForm(p => ({ ...p, [k]: v })); setError(""); };
  const closeForm = () => { sound("click"); setFormType(null); setEditingId(null); setError(""); };
  const openCreate = () => { sound("open"); refresh(); setEditingId(null); setViewType(null); setError(""); if (activeTab === "selection") { setSelectionForm(emptySelection()); setFormType("selection"); } else { setDeliveryForm(emptyDelivery()); setFormType("delivery"); } };
  const findExistingCustomer = item => customers.find(c => item.customerId && String(c.id) === String(item.customerId)) || customers.find(c => phoneOf(item) && phoneOf(c) === phoneOf(item)) || customers.find(c => nameOf(c).toLowerCase() === String(item.customer || "").trim().toLowerCase());
  const openEdit = (kind, item) => { sound("open"); refresh(); const c = findExistingCustomer(item); const data = { ...(kind === "delivery" ? emptyDelivery() : emptySelection()), ...item, customerId: c ? String(c.id) : "", customer: c ? nameOf(c) : item.customer, phone: c ? phoneOf(c) : item.phone, email: c ? emailOf(c) : item.email || "", ...(kind === "delivery" && c ? { address: item.address || addressOf(c) } : {}) }; if (kind === "delivery") setDeliveryForm(data); else setSelectionForm(data); setEditingId(item.id); setViewType(null); setError(""); setFormType(kind); };
  const fail = msg => { setError(msg); sound("error"); };
  const registeredCustomer = id => customers.find(c => String(c.id) === String(id));
  const saveDelivery = async e => {
    e.preventDefault();
    const c = registeredCustomer(deliveryForm.customerId);
    const customer = String(deliveryForm.customer || "").trim();
    const phone = phoneOf(deliveryForm.phone);
    if (!customer) return fail("Please enter customer name or select a registered customer.");
    const quantity = Number(deliveryForm.quantity);
    if (!Number.isInteger(quantity) || quantity < 1) return fail("Quantity must be at least 1.");
    if (deliveryForm.status === "Delivered" && !deliveryForm.deliveredDate) return fail("Please select actual delivery date.");
    if (["Courier", "Home Delivery"].includes(deliveryForm.deliveryMethod) && !String(deliveryForm.address || "").trim()) return fail("Please enter delivery address.");
    
    let recordId = editingId || makeId("DEL");
    if (editingId) {
      try {
        await api.deliveries.update(editingId, {
          customer_name: customer,
          phone,
          address: deliveryForm.address || "",
          item_name: deliveryForm.item || "Album",
          quantity,
          delivery_date: deliveryForm.deliveredDate || deliveryForm.expectedDate || null,
          status: deliveryForm.status || "Pending",
          payment_status: deliveryForm.paymentStatus || "Pending",
          tracking_number: deliveryForm.trackingNumber || "",
          notes: deliveryForm.notes || "",
        });
      } catch (err) {
        console.warn("Backend delivery update notice:", err.message);
      }
    } else {
      try {
        const remote = await api.deliveries.create({
          customer_name: customer,
          phone,
          address: deliveryForm.address || "",
          item_name: deliveryForm.item || "Album",
          quantity,
          delivery_date: deliveryForm.deliveredDate || deliveryForm.expectedDate || null,
          status: deliveryForm.status || "Pending",
          payment_status: deliveryForm.paymentStatus || "Pending",
          tracking_number: deliveryForm.trackingNumber || "",
          notes: deliveryForm.notes || "",
        });
        if (remote && remote.id) recordId = remote.id;
      } catch (err) {
        console.warn("Backend delivery create notice:", err.message);
      }
    }
    const record = { ...deliveryForm, id: recordId, customerId: c ? String(c.id) : "", customer, phone, quantity, assignedTo: deliveryForm.assignedTo || "Not Assigned" };
    setDeliveries(p => editingId ? p.map(x => x.id === editingId ? record : x) : [record, ...p]);
    sound("success"); setFormType(null); setEditingId(null); setError(""); setStatusError("");
  };
  const saveSelection = e => {
    e.preventDefault();
    const c = registeredCustomer(selectionForm.customerId);
    const customer = String(selectionForm.customer || "").trim();
    const phone = phoneOf(selectionForm.phone);
    if (!customer) return fail("Please enter customer name or select a registered customer.");
    const total = Number(selectionForm.photoCount || 0), selected = Number(selectionForm.selectedCount || 0);
    if (!selectionForm.givenDate || !selectionForm.dueDate) return fail("Please select given date and return date.");
    if (selectionForm.dueDate < selectionForm.givenDate) return fail("Return date cannot be before given date.");
    if (selectionForm.returnedDate && selectionForm.returnedDate < selectionForm.givenDate) return fail("Actual return date cannot be before given date.");
    if (![total, selected].every(n => Number.isInteger(n) && n >= 0)) return fail("Photo counts must be valid whole numbers.");
    if (selected > total) return fail("Selected photos cannot exceed shared photos.");
    const record = { ...selectionForm, id: editingId || makeId("SEL"), customerId: c ? String(c.id) : "", customer, phone, photoCount: total, selectedCount: selected, assignedTo: selectionForm.assignedTo || "Not Assigned" };
    setSelections(p => editingId ? p.map(x => x.id === editingId ? record : x) : [record, ...p]);
    sound("success"); setFormType(null); setEditingId(null); setError("");
  };
  const deleteRecord = async (kind, id) => {
    sound("click");
    if (!window.confirm(`Delete this ${kind === "delivery" ? "delivery" : "photo selection"} record?`)) return;
    if (kind === "delivery") {
      try { await api.deliveries.delete(id); } catch (err) { console.warn("Backend delivery delete notice:", err.message); }
      setDeliveries(p => p.filter(x => x.id !== id));
    } else {
      setSelections(p => p.filter(x => x.id !== id));
    }
    if (viewId === id) setViewType(null);
    sound("delete");
  };
  const changeStatus = (item, status) => { setStatusError(""); if (status === item.status) return; if (status === "Delivered" && !item.deliveredDate) { setStatusError(`Confirm the actual delivery date for ${item.customer}.`); setDeliveryForm({ ...emptyDelivery(), ...item, status: "Delivered", deliveredDate: todayKey() }); setEditingId(item.id); setFormType("delivery"); sound("error"); return; } setDeliveries(p => p.map(d => d.id === item.id ? { ...d, status } : d)); sound("success"); };
  const markReturned = item => { sound("click"); if (!window.confirm(`Mark ${item.customer}'s photo selection as returned today?`)) return false; setSelections(p => p.map(s => s.id === item.id ? { ...s, returnedDate: todayKey() } : s)); sound("success"); return true; };
  const filteredD = useMemo(() => deliveries.filter(x => [x.id, x.customerId, x.bookingId, x.customer, x.phone, x.event, x.item, x.trackingNumber, x.assignedTo, x.courier, x.deliveryMethod, x.address].some(v => String(v ?? "").toLowerCase().includes(search.trim().toLowerCase())) && (filter === "All" || x.status === filter)), [deliveries, search, filter]);
  const filteredS = useMemo(() => selections.filter(x => [x.id, x.customerId, x.bookingId, x.customer, x.phone, x.project, x.method, x.assignedTo, x.notes].some(v => String(v ?? "").toLowerCase().includes(search.trim().toLowerCase())) && (filter === "All" || selectionStatus(x) === filter)), [selections, search, filter]);
  const selectionStats = { total: selections.length, pending: selections.filter(s => selectionStatus(s) === "Pending").length, overdue: selections.filter(s => selectionStatus(s) === "Overdue").length, returned: selections.filter(s => selectionStatus(s) === "Returned").length };
  const deliveryStats = { total: deliveries.length, pending: deliveries.filter(d => ["Pending", "Packed"].includes(d.status)).length, dispatched: deliveries.filter(d => d.status === "Dispatched").length, delivered: deliveries.filter(d => d.status === "Delivered").length };
  const overdue = selections.filter(s => selectionStatus(s) === "Overdue").sort((a, b) => String(a.dueDate || "").localeCompare(String(b.dueDate || "")));
  const selectedView = viewType === "selection" ? selections.find(s => s.id === viewId) : viewType === "delivery" ? deliveries.find(d => d.id === viewId) : null;
  const isSelection = activeTab === "selection", filtered = isSelection ? filteredS : filteredD, total = isSelection ? selections.length : deliveries.length;
  const exportCSV = () => { const columns = isSelection ? ["id", "customerId", "bookingId", "customer", "phone", "project", "givenDate", "dueDate", "returnedDate", "photoCount", "selectedCount", "method", "assignedTo", "notes", "status"] : ["id", "customerId", "bookingId", "customer", "phone", "event", "item", "quantity", "deliveryMethod", "address", "courier", "trackingNumber", "expectedDate", "deliveredDate", "assignedTo", "paymentStatus", "status", "notes"]; const records = isSelection ? filteredS.map(s => ({ ...s, status: selectionStatus(s) })) : filteredD; const escape = v => { const str = String(v ?? ""); const safe = /^\s*[=+\-@\t\r]/.test(str) ? `'${str}` : str; return `"${safe.replace(/"/g, '""')}"`; }; const csv = [columns.map(escape).join(","), ...records.map(r => columns.map(c => escape(r[c])).join(","))].join("\r\n"); const url = URL.createObjectURL(new Blob(["\uFEFF", csv], { type: "text/csv;charset=utf-8;" })); const a = document.createElement("a"); a.href = url; a.download = isSelection ? "studioraw_photo_selections.csv" : "studioraw_deliveries.csv"; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000); sound("success"); };
  const switchTab = tab => { sound("click"); setActiveTab(tab); setSearch(""); setFilter("All"); setStatusError(""); };


  return <div className="min-h-screen w-full min-w-0 overflow-x-hidden bg-gradient-to-br from-[#f9fcff] via-[#f0f7ff] to-[#e5f1ff] px-3 py-5 text-[#102b53] sm:px-5 sm:py-7 lg:px-8 lg:py-8"><div className="mb-6 flex flex-wrap items-center justify-end gap-2"><button onClick={exportCSV} className="flex min-h-11 flex-1 items-center justify-center gap-2 rounded-xl border border-[#d6e7fa] bg-white px-4 py-2.5 text-xs font-bold sm:flex-none sm:text-sm"><Download size={17}/>Export CSV</button><button onClick={openCreate} className="flex min-h-11 flex-1 items-center justify-center gap-2 rounded-xl bg-[#173b70] px-4 py-2.5 text-xs font-bold text-white sm:flex-none sm:text-sm"><Plus size={18}/>{isSelection ? "New Photo Selection" : "New Delivery"}</button></div><div className="mb-6 flex flex-wrap gap-2 rounded-[20px] border border-[#d6e7fa] bg-white p-2 shadow-sm"><button onClick={() => switchTab("selection")} className={`flex flex-1 items-center justify-center gap-2 rounded-2xl px-3 py-3 text-xs font-bold sm:flex-none sm:px-6 sm:text-sm ${isSelection ? "bg-gradient-to-br from-[#173b70] to-[#3265a8] text-white" : "text-[#385d89] hover:bg-[#edf5ff]"}`}><Images size={17}/>Photo Selection <span className="rounded-full bg-white/20 px-2 py-0.5 text-[10px]">{selections.length}</span></button><button onClick={() => switchTab("delivery")} className={`flex flex-1 items-center justify-center gap-2 rounded-2xl px-3 py-3 text-xs font-bold sm:flex-none sm:px-6 sm:text-sm ${!isSelection ? "bg-gradient-to-br from-[#173b70] to-[#3265a8] text-white" : "text-[#385d89] hover:bg-[#edf5ff]"}`}><Truck size={17}/>Deliveries <span className="rounded-full bg-white/20 px-2 py-0.5 text-[10px]">{deliveries.length}</span></button></div><div className="mb-6 grid grid-cols-2 gap-3 sm:gap-4 xl:grid-cols-4">{isSelection ? <><Stat title="Photos Given" value={selectionStats.total} icon={Images} detail="Total selection records"/><Stat title="Awaiting Return" value={selectionStats.pending} icon={Clock3} tone="amber" detail="Within return deadline"/><Stat title="Overdue Selections" value={selectionStats.overdue} icon={BellRing} tone="red" detail="Customer follow-up needed"/><Stat title="Photos Returned" value={selectionStats.returned} icon={CheckCircle2} tone="green" detail="Completed selections"/></> : <><Stat title="Total Deliveries" value={deliveryStats.total} icon={Package}/><Stat title="Pending Deliveries" value={deliveryStats.pending} icon={Clock3} tone="amber"/><Stat title="Dispatched" value={deliveryStats.dispatched} icon={Truck} tone="purple"/><Stat title="Delivered" value={deliveryStats.delivered} icon={CheckCircle2} tone="green"/></>}</div>{isSelection && overdue.length > 0 && <section className="mb-6 rounded-[22px] border border-rose-200 bg-gradient-to-r from-rose-50 via-orange-50 to-amber-50 p-4 shadow-sm sm:p-5"><div className="flex items-start gap-3"><div className="rounded-2xl bg-rose-100 p-3 text-rose-600"><BellRing size={20}/></div><div><h3 className="text-sm font-extrabold text-rose-900 sm:text-base">Smart Follow-up Alert</h3><p className="mt-1 text-xs leading-5 text-rose-800">{overdue.length} customers have not returned their photo selections within the expected date.</p></div></div><div className="mt-4 flex flex-wrap gap-2">{overdue.slice(0, 5).map(s => <button key={s.id} onClick={() => { sound("open"); setViewType("selection"); setViewId(s.id); }} className="rounded-xl border border-rose-200 bg-white px-3 py-2 text-xs font-semibold text-rose-800">{s.customer} · {daysBetween(s.dueDate, todayKey())}d late</button>)}</div></section>}<section className="min-w-0 rounded-[24px] border border-[#d6e7fa] bg-white shadow-sm"><div className="border-b border-[#d6e7fa] p-4 sm:p-5 lg:p-6"><div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between"><div><h2 className="flex items-center gap-2 text-lg font-extrabold">{isSelection ? <Images size={21}/> : <ClipboardList size={21}/>} {isSelection ? "Photo Selection Records" : "Delivery Records"}</h2><p className="mt-1 text-xs text-[#748eae]">Showing {filtered.length} of {total} records</p></div><div className="flex w-full flex-col gap-3 sm:flex-row xl:w-auto"><div className="relative w-full sm:flex-1 xl:w-72"><Search size={17} className="pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2 text-[#748eae]"/><input type="search" value={search} onChange={e => setSearch(e.target.value)} placeholder={isSelection ? "Search photo selections..." : "Search deliveries..."} className={`${inputClass} pl-10`}/></div><div className="flex w-full items-center gap-2 sm:w-52"><Filter size={17} className="shrink-0 text-[#385d89]"/><Select value={filter} options={isSelection ? ["All", "Pending", "Overdue", "Returned"] : ["All", ...DELIVERY_STATUSES]} onChange={setFilter}/></div></div></div></div>{statusError && <div className="mx-4 mt-4 flex items-start gap-2 rounded-xl border border-amber-200 bg-amber-50 p-3 text-xs text-amber-800"><AlertCircle size={17}/><span className="flex-1">{statusError}</span><button onClick={() => setStatusError("")}><X size={15}/></button></div>}{filtered.length === 0 ? <div className="flex flex-col items-center justify-center px-4 py-16 text-center"><div className="rounded-3xl bg-[#e0efff] p-5 text-[#24558d]">{isSelection ? <Images size={35}/> : <Truck size={35}/>}</div><h3 className="mt-4 font-extrabold">No records found</h3><p className="mt-2 text-sm text-[#748eae]">Try another search or create a new record.</p><button onClick={openCreate} className="mt-5 flex items-center gap-2 rounded-xl bg-[#173b70] px-5 py-3 text-xs font-bold text-white"><Plus size={16}/>Add New Record</button></div> : <div className="grid grid-cols-1 items-stretch gap-3 p-3 sm:grid-cols-2 sm:gap-4 sm:p-5 2xl:grid-cols-3">{isSelection ? filteredS.map(item => <SelectionCard key={item.id} item={item} onView={x => { sound("open"); setViewType("selection"); setViewId(x.id); }} onEdit={x => openEdit("selection", x)} onDelete={id => deleteRecord("selection", id)} onReturn={markReturned}/>) : filteredD.map(item => <DeliveryCard key={item.id} item={item} onView={x => { sound("open"); setViewType("delivery"); setViewId(x.id); }} onEdit={x => openEdit("delivery", x)} onDelete={id => deleteRecord("delivery", id)} onStatus={changeStatus}/>)}</div>}<div className="flex flex-col gap-2 border-t border-[#d6e7fa] px-4 py-4 text-xs text-[#748eae] sm:flex-row sm:justify-between sm:px-6"><span>Showing {filtered.length} of {total} records</span><span>Studio Raw Picturez ERP</span></div></section>
  {formType === "selection" && <Modal title={editingId ? "Edit Photo Selection" : "New Photo Selection"} description="Track photos shared with customers and their return dates" icon={Images} onClose={closeForm} onSubmit={saveSelection} submitLabel={editingId ? "Update Selection" : "Save Photo Selection"}><div className="rounded-2xl border border-[#d3e5fa] bg-gradient-to-r from-[#edf6ff] to-[#e2efff] p-4"><div className="flex gap-3"><Sparkles size={20} className="shrink-0 text-[#24558d]"/><div><p className="text-sm font-bold">Smart Photo Selection Tracking</p><p className="mt-1 text-xs text-[#58769c]">Select an existing customer or enter details manually. Overdue status is calculated from dates.</p></div></div></div><Section icon={UserRound} title="Customer Information" subtitle="Select existing customer or enter customer details manually"><CustomerFields kind="selection" deliveryForm={deliveryForm} selectionForm={selectionForm} deliveryBookings={deliveryBookings} selectionBookings={selectionBookings} updateD={updateD} updateS={updateS} chooseCustomer={chooseCustomer} chooseBooking={chooseBooking} customerOptions={customerOptions} registeredCustomer={registeredCustomer}/></Section><Section icon={CalendarClock} title="Photo Selection Timeline" subtitle="Given date, expected return and actual return"><div className="grid grid-cols-1 gap-4"><Field label="Photos Given Date" required><input required type="date" value={selectionForm.givenDate} onChange={e => updateS("givenDate", e.target.value)} className={inputClass}/></Field><Field label="Expected Return Date" required><input required type="date" min={selectionForm.givenDate || undefined} value={selectionForm.dueDate} onChange={e => updateS("dueDate", e.target.value)} className={inputClass}/></Field><Field label="Actual Return Date"><input type="date" min={selectionForm.givenDate || undefined} value={selectionForm.returnedDate} onChange={e => updateS("returnedDate", e.target.value)} className={inputClass}/></Field></div><div className="mt-4 flex items-center justify-between rounded-2xl border border-[#d6e7fa] bg-[#edf5ff] p-4"><div><p className="text-[11px] font-semibold text-[#748eae]">Automatic Selection Status</p><p className="mt-1 text-xs">Calculated from entered dates</p></div><StatusBadge value={selectionStatus(selectionForm)}/></div></Section><Section icon={ImageIcon} title="Photo Selection Details" subtitle="Shared photos, selected photos and sharing method"><div className="grid grid-cols-1 gap-4"><Field label="Total Photos Shared"><input type="number" min="0" step="1" value={selectionForm.photoCount} onChange={e => updateS("photoCount", e.target.value)} placeholder="e.g. 1200" className={inputClass}/></Field><Field label="Photos Selected"><input type="number" min="0" step="1" value={selectionForm.selectedCount} onChange={e => updateS("selectedCount", e.target.value)} placeholder="e.g. 150" className={inputClass}/></Field><Field label="Photos Shared Through"><Select value={selectionForm.method} options={SELECTION_METHODS} onChange={v => updateS("method", v)}/></Field><Field label="Assigned Staff"><Select value={selectionForm.assignedTo} options={STAFF} onChange={v => updateS("assignedTo", v)}/></Field><div className=""><Field label="Selection Notes"><textarea rows={3} value={selectionForm.notes} onChange={e => updateS("notes", e.target.value)} placeholder="Customer follow-up and special instructions..." className={inputClass}/></Field></div></div></Section>{error && <div role="alert" className="flex items-start gap-2 rounded-xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-800"><AlertCircle size={18}/>{error}</div>}</Modal>}
  {formType === "delivery" && <Modal title={editingId ? "Edit Delivery" : "New Delivery"} description="Select customer and enter delivery information" icon={Truck} onClose={closeForm} onSubmit={saveDelivery} submitLabel={editingId ? "Update Delivery" : "Save Delivery"}><Section icon={UserRound} title="Customer Information" subtitle="Select existing customer or enter customer details manually"><CustomerFields kind="delivery" deliveryForm={deliveryForm} selectionForm={selectionForm} deliveryBookings={deliveryBookings} selectionBookings={selectionBookings} updateD={updateD} updateS={updateS} chooseCustomer={chooseCustomer} chooseBooking={chooseBooking} customerOptions={customerOptions} registeredCustomer={registeredCustomer}/></Section><Section icon={Truck} title="Delivery Information"><div className="grid grid-cols-1 gap-4"><Field label="Delivery Method"><Select value={deliveryForm.deliveryMethod} options={DELIVERY_METHODS} onChange={v => updateD("deliveryMethod", v)}/></Field><Field label="Quantity" required><input required type="number" min="1" step="1" value={deliveryForm.quantity} onChange={e => updateD("quantity", e.target.value)} className={inputClass}/></Field>{["Courier", "Home Delivery"].includes(deliveryForm.deliveryMethod) && <div className=""><Field label="Delivery Address" required><textarea required rows={3} value={deliveryForm.address} onChange={e => updateD("address", e.target.value)} placeholder="Delivery address (auto-filled, editable if needed)" className={inputClass}/></Field></div>}{deliveryForm.deliveryMethod === "Courier" && <><Field label="Courier Company"><Select value={deliveryForm.courier} options={COURIERS} onChange={v => updateD("courier", v)}/></Field><Field label="Tracking Number"><input value={deliveryForm.trackingNumber} onChange={e => updateD("trackingNumber", e.target.value)} placeholder="Tracking number" className={inputClass}/></Field></>}<Field label="Expected Delivery Date"><input type="date" value={deliveryForm.expectedDate} onChange={e => updateD("expectedDate", e.target.value)} className={inputClass}/></Field><Field label="Actual Delivery Date"><input type="date" value={deliveryForm.deliveredDate} onChange={e => updateD("deliveredDate", e.target.value)} className={inputClass}/></Field><div className=""><Field label="Assigned Staff"><Select value={deliveryForm.assignedTo} options={STAFF} onChange={v => updateD("assignedTo", v)}/></Field></div></div></Section><Section icon={CreditCard} title="Payment & Status"><div className="grid grid-cols-1 gap-4"><Field label="Payment Status"><Select value={deliveryForm.paymentStatus} options={PAYMENT_STATUSES} onChange={v => updateD("paymentStatus", v)}/></Field><Field label="Delivery Status"><Select value={deliveryForm.status} options={DELIVERY_STATUSES} onChange={v => updateD("status", v)}/></Field><div className=""><Field label="Delivery Notes"><textarea rows={3} value={deliveryForm.notes} onChange={e => updateD("notes", e.target.value)} placeholder="Enter special instructions..." className={inputClass}/></Field></div></div></Section>{error && <div role="alert" className="flex items-start gap-2 rounded-xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-800"><AlertCircle size={18}/>{error}</div>}</Modal>}
  {viewType && selectedView && <Modal title={viewType === "selection" ? "Photo Selection Details" : "Delivery Details"} description={selectedView.customer} icon={viewType === "selection" ? Images : Package} onClose={() => { sound("click"); setViewType(null); }} maxWidth="max-w-[700px]"><div className="mb-5 flex items-center justify-between rounded-2xl bg-gradient-to-r from-[#edf6ff] to-[#dcecff] p-5"><h3 className="text-lg font-extrabold text-[#102b53]">{selectedView.customer}</h3><StatusBadge value={viewType === "selection" ? selectionStatus(selectedView) : selectedView.status}/></div><div className="grid grid-cols-2 gap-3"><Info label="Customer" value={selectedView.customer} icon={UserRound}/><Info label="Phone" value={selectedView.phone} icon={Phone}/>{selectedView.customerId && <Info label="Customer Profile ID" value={selectedView.customerId} icon={Hash}/>} {selectedView.bookingId && <Info label="Linked Booking" value={selectedView.bookingId} icon={Camera}/>} {viewType === "selection" ? <><div className="col-span-2"><Info label="Photography Package" value={selectedView.project} icon={Camera}/></div><Info label="Photos Given Date" value={formatDate(selectedView.givenDate)} icon={CalendarDays}/><Info label="Expected Return Date" value={formatDate(selectedView.dueDate)} icon={CalendarClock}/><Info label="Actual Return Date" value={formatDate(selectedView.returnedDate)} icon={CheckCircle2}/><Info label="Sharing Method" value={selectedView.method} icon={Images}/><Info label="Total Photos Shared" value={selectedView.photoCount} icon={ImageIcon}/><Info label="Photos Selected" value={selectedView.selectedCount} icon={CheckCircle2}/></> : <><Info label="Event" value={selectedView.event} icon={Camera}/><Info label="Delivery Item" value={selectedView.item} icon={Package}/><Info label="Quantity" value={selectedView.quantity} icon={Box}/><Info label="Delivery Method" value={selectedView.deliveryMethod} icon={Truck}/><Info label="Expected Date" value={formatDate(selectedView.expectedDate)} icon={CalendarDays}/><Info label="Actual Date" value={formatDate(selectedView.deliveredDate)} icon={CheckCircle2}/><Info label="Payment Status" icon={CreditCard}><StatusBadge value={selectedView.paymentStatus} payment/></Info>{selectedView.address && <div className="col-span-2"><Info label="Delivery Address" value={selectedView.address} icon={MapPin}/></div>}{selectedView.courier && <Info label="Courier" value={selectedView.courier} icon={Building2}/>} {selectedView.trackingNumber && <Info label="Tracking Number" value={selectedView.trackingNumber} icon={Hash}/>}</>}<div className="col-span-2"><Info label="Assigned Staff" value={selectedView.assignedTo} icon={UserRound}/></div>{selectedView.notes && <div className="col-span-2"><Info label="Notes" value={selectedView.notes} icon={FileText}/></div>}</div><div className="mt-5 flex gap-2">{viewType === "selection" && selectionStatus(selectedView) !== "Returned" && <button onClick={() => { if (markReturned(selectedView)) setViewType(null); }} className="flex flex-1 items-center justify-center gap-2 rounded-xl bg-emerald-600 px-5 py-3 text-sm font-bold text-white"><CheckCircle2 size={17}/>Mark Returned</button>}<button onClick={() => openEdit(viewType, selectedView)} className="flex flex-1 items-center justify-center gap-2 rounded-xl bg-[#173b70] px-5 py-3 text-sm font-bold text-white"><Pencil size={16}/>Edit {viewType === "selection" ? "Selection" : "Delivery"}</button></div></Modal>}
  </div>;
}
